func:
// "Konsey" sayfasindaki "Konseyi topla" dugmesi. Proje metnini dogrular.
// Cikis 1 -> pano (onceki isimler) okunur, konsey toplanir
// Cikis 2 -> girdi gecersiz: dogrudan uyari (view action) -- AI'a gitmez

const veri = (msg.payload && msg.payload.data) || (msg.submission && msg.submission.data) || msg.submission || {};
const proje = String(veri.proje || "").replace(/\s+/g, " ").trim();

function uyar(metin) {
  msg.messages = { mesaj: metin };
  msg.submission = { proje: proje, sahne: '<div class="konsey-uyari">\u26A0\uFE0F ' + metin + '</div>' };
  return [null, msg];
}
if (proje.length < 15) return uyar("Konsey bos bir dosyayla toplanmaz. Projeni en az bir-iki cumleyle anlat.");
if (proje.length > 400) return uyar("Konsey sabirsizdir: projeni en fazla 400 karakterde, iki cumleyle anlat (" + proje.length + " karakter yazdin).");

msg.proje = proje;
node.status({ fill: "blue", shape: "dot", text: proje.slice(0, 30) + "..." });
return [msg, null];

// Konseyi kurar: oturuma ozel ilham konulari secer, panodaki isimleri
// "yasakli" listesine alir. Sonra 03-sonraki-konusmaci.js ilk konusmaciyi cagirir.
//
// Neden ilham + yasak liste: ayni proje icin bile her oturum farkli tonda
// isim ciksin, panoda ayni isim iki kez olmasin. Bicim ise ajanlarin
// Output Schema'si ile sabit kalir.
//
// Girdi: msg.payload = pano.jsonl icerigi (file in) ya da "" (ilk kullanim)

const ILHAM = {
  muhendis: ["eski hata kodlari", "COBOL ve ana bilgisayarlar", "bitmeyen toplantilar", "Unix komutlari", "kahve makinesi",
             "uretimde cuma deploy'u", "yari kalmis dokumantasyon", "legacy kod arkeolojisi", "ag kablosu karmasasi"],
  pazarlamaci: ["uzay yarisi", "luks otomobil reklamlari", "spor finali spikerligi", "Silikon Vadisi lansmanlari",
                "superkahraman filmleri", "moda haftasi", "teleshopping", "olimpiyat tores", "rock konseri"],
  sair: ["deniz ve fener", "kuzey yildizi", "Anadolu masallari", "sonbahar yapraklari", "kayip mektuplar",
         "eski Istanbul vapurlari", "col ve serap", "ay tutulmasi", "goc eden kuslar"]
};
const sec = (a) => a[Math.floor(Math.random() * a.length)];

const pano = [];
for (const satir of String(msg.payload || "").split(/\r?\n/)) {
  if (!satir.trim()) continue;
  try { pano.push(JSON.parse(satir)); } catch (e) {}
}

msg.konsey = {
  proje: msg.proje,
  ilham: { muhendis: sec(ILHAM.muhendis), pazarlamaci: sec(ILHAM.pazarlamaci), sair: sec(ILHAM.sair) },
  yasakli: pano.map(p => p.kodAdi).filter(Boolean).slice(-30),
  konusmalar: [],          // [{ karakter, kodAdi, gerekce }]
  bekleyen: null
};
msg.panoKayitlari = pano;   // 04-karar-isle.js kazananin sirasini bununla hesaplar
msg.payload = null;
node.status({ fill: "blue", shape: "dot", text: "konsey toplaniyor (" + pano.length + " isim panoda)" });
return msg;

// Konseyin "sira yoneticisi". Her ajan cevabindan sonra buraya donulur:
//   1) az once konusanin cevabini kaydeder (Output Schema: { kodAdi, gerekce })
//   2) siradaki konusmacinin prompt'unu kurar ve dogru cikisa yollar
//
// Cikislar: 1 muhendis | 2 pazarlamaci | 3 sair | 4 baskan | 5 hata
//
// Karakterlerin KISILIGI ajan dugumunun Instructions alaninda (akis-uret.py);
// burada sadece o oturumun gorevi ve baglami var. Boylece ses ajan basina
// sabit, icerik her oturumda farkli.

const SIRA = ["muhendis", "pazarlamaci", "sair"];
const AD = { muhendis: "Alayci Muhendis", pazarlamaci: "Abartili Pazarlamaci", sair: "Dramatik Sair" };
const k = msg.konsey;
const NL = String.fromCharCode(10);

function temiz(s, enfazla) { return String(s || "").replace(/\s+/g, " ").trim().slice(0, enfazla); }

// 1) az once konusani kaydet
if (k.bekleyen) {
  const p = msg.payload || {};
  const kodAdi = temiz(p.kodAdi, 40);
  const gerekce = temiz(p.gerekce, 600);
  if (!kodAdi || !gerekce) {
    msg.hata = AD[k.bekleyen] + " anlasilmaz bir sey mirildandi (bos isim/gerekce).";
    return [null, null, null, null, msg];
  }
  k.konusmalar.push({ karakter: k.bekleyen, kodAdi: kodAdi, gerekce: gerekce });
  k.bekleyen = null;
}

// 2) siradaki
const siradaki = SIRA[k.konusmalar.length];
const onceki = k.konusmalar.map(x => "- " + AD[x.karakter] + ": \"" + x.kodAdi + "\" -- " + x.gerekce).join(NL);

if (siradaki) {
  k.bekleyen = siradaki;
  msg.payload = [
    "Kod Adi Konseyi toplandi. Bir proje icin KOD ADI oneriyorsun.",
    "",
    "PROJE: " + k.proje,
    "",
    "Bu oturumdaki ilham kaynagin: " + k.ilham[siradaki] + " (istersen kullan, zorunlu degil).",
    onceki ? "Senden once konusanlar:" + NL + onceki + NL + "Onlardan FARKLI bir isim oner; istersen onlara kendi uslubunla laf at." : "Ilk sen konusuyorsun.",
    k.yasakli.length ? "Bu isimler panoda zaten var, KULLANMA: " + k.yasakli.join(", ") : "",
    "",
    "Kurallar:",
    "- kodAdi: 1-3 kelime, en fazla 24 karakter. Turkce ya da Ingilizce olabilir.",
    "- gerekce: 2-3 cumle, en fazla 60 kelime, TAMAMEN kendi karakterinin sesiyle.",
    "- Projeyle gercek bir bag kur; sadece komik olsun diye alakasiz isim verme."
  ].filter(s => s !== "").join(NL);
  k.sonPrompt = msg.payload; k.sonHedef = SIRA.indexOf(siradaki); k.deneme = 1;   // 07-ajan-yeniden.js icin
  node.status({ fill: "blue", shape: "dot", text: AD[siradaki] + " konusuyor..." });
  const cikis = [null, null, null, null, null];
  cikis[SIRA.indexOf(siradaki)] = msg;
  return cikis;
}

// 3) uc uye de konustu -> Baskan
msg.payload = [
  "Kod Adi Konseyi'nin baskanisin. Uc uyeyi dinledin, simdi karar veriyorsun.",
  "",
  "PROJE: " + k.proje,
  "",
  "ONERILER:",
  k.konusmalar.map(x => "- [" + x.karakter + "] " + AD[x.karakter] + ": \"" + x.kodAdi + "\" -- " + x.gerekce).join(NL),
  "",
  "Gorevin:",
  "1. degerlendirmeler.muhendis / .pazarlamaci / .sair: HER UYEYE ayri ayri, onun uslubuna ve onerisine",
  "   dogrudan degin (1-2 cumle, adini ya da onerdigi ismi an).",
  "2. Tek bir kazanan sec. kazananKarakter alanina karakter anahtarini yaz (muhendis | pazarlamaci | sair),",
  "   kazanan alanina o uyenin onerdigi ismi AYNEN yaz.",
  "3. puan: kazanan isme 1-100 arasi tam sayi (akilda kalicilik, projeye uygunluk, ozgunluk).",
  "4. karar: 2-3 cumlelik gerekceli karar; hafif esprili, ama adil."
].join(NL);
k.sonPrompt = msg.payload; k.sonHedef = 3; k.deneme = 1;
node.status({ fill: "blue", shape: "dot", text: "Baskan karar veriyor..." });
return [null, null, null, msg, null];

// Baskanin kararini (Output Schema) dogrular, panoya eklenecek kaydi ve
// "Konsey" sayfasinda gosterilecek sahneyi (HTML) uretir.
//
// Model ciktisina guvenmiyoruz: kazananKarakter gecersizse isimden buluruz,
// puan araliga sikistirilir, eksik degerlendirme "(sessiz kaldi)" olur.
// Gorunum bozulmasin diye butun metinler HTML-escape edilir.
//
// Cikis 1 -> pano.jsonl'e eklenecek satir (file, append)  -- sadece kazananlar
// Cikis 3 -> oturumlar/<YYYY-MM-DD>.jsonl (file, append)    -- oturumun TAM kaydi:
//            proje, ilhamlar, uc oneri + gerekceleri, Baskanin notlari, kazanan, puan
// Cikis 2 -> view action: sahne msg.submission.sahne'ye (sayfada kalici kutu),
//            uyari kutusuna kisa ozet (aXet uyarilari 10 sn'de siliniyor)

const AD = { muhendis: "Alayci Muhendis", pazarlamaci: "Abartili Pazarlamaci", sair: "Dramatik Sair" };
const IKON = { muhendis: "\u{1F6E0}\u{FE0F}", pazarlamaci: "\u{1F4E3}", sair: "\u{1F3AD}", baskan: "⚖\u{FE0F}" };
const k = msg.konsey;
const b = msg.payload || {};
const esc = (s) => String(s === undefined || s === null ? "" : s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const sade = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");

// --- kazanan: once karakter anahtari, olmazsa isim eslesmesi, olmazsa ilk oneri
let kazanan = k.konusmalar.find(x => x.karakter === b.kazananKarakter);
if (!kazanan) kazanan = k.konusmalar.find(x => sade(x.kodAdi) === sade(b.kazanan));
if (!kazanan) kazanan = k.konusmalar.find(x => sade(b.kazanan).includes(sade(x.kodAdi)) && sade(x.kodAdi));
if (!kazanan) { kazanan = k.konusmalar[0]; node.warn("Baskan gecerli bir kazanan vermedi, ilk oneri secildi: " + JSON.stringify(b).slice(0, 200)); }

let puan = Math.round(Number(b.puan));
if (!isFinite(puan)) puan = 50;
puan = Math.max(1, Math.min(100, puan));

const deg = b.degerlendirmeler || {};
const karar = String(b.karar || "Konsey karar verdi.").trim();

const kayit = {
  zaman: new Date().toISOString(),
  kodAdi: kazanan.kodAdi,
  puan: puan,
  karakter: kazanan.karakter,
  proje: k.proje.slice(0, 160),
  karar: karar.slice(0, 500),
  oneriler: k.konusmalar.map(x => ({ karakter: x.karakter, kodAdi: x.kodAdi }))
};

// --- panodaki sira (bu kayit dahil)
const pano = (msg.panoKayitlari || []).concat([kayit]);
pano.sort((x, y) => y.puan - x.puan || x.zaman.localeCompare(y.zaman));
const sira = pano.indexOf(kayit) + 1;

// --- sahne
const kart = (x) =>
  '<div class="konsey-kart konsey-' + x.karakter + (x === kazanan ? ' konsey-kazanan' : '') + '">' +
    '<div class="konsey-kim">' + IKON[x.karakter] + ' ' + esc(AD[x.karakter]) + '</div>' +
    '<div class="konsey-isim">&laquo;' + esc(x.kodAdi) + '&raquo;</div>' +
    '<div class="konsey-gerekce">' + esc(x.gerekce) + '</div>' +
    '<div class="konsey-baskan-notu">' + IKON.baskan + ' ' + esc(deg[x.karakter] || "(Baskan bu uyeye bir sey demedi.)") + '</div>' +
  '</div>';

const sahne =
    '<div class="konsey-sahne">' +
      '<div class="konsey-baslik">Kod Adi Konseyi toplandi</div>' +
      '<div class="konsey-proje">' + esc(k.proje) + '</div>' +
      '<div class="konsey-kartlar">' + k.konusmalar.map(kart).join("") + '</div>' +
      '<div class="konsey-karar">' +
        '<div class="konsey-karar-ust">' + IKON.baskan + ' Baskanin karari</div>' +
        '<div class="konsey-karar-isim">&laquo;' + esc(kazanan.kodAdi) + '&raquo; <span class="konsey-puan">' + puan + '/100</span></div>' +
        '<div class="konsey-karar-metin">' + esc(karar) + '</div>' +
        '<div class="konsey-pano-notu">Isim Panosu\'na eklendi: <b>' + sira + '. sira</b> (' + pano.length + ' isim arasinda).</div>' +
      '</div>' +
    '</div>';
msg.submission = { proje: k.proje, sahne: sahne };
msg.messages = { ozet: "Konsey karar verdi: \u00AB" + kazanan.kodAdi + "\u00BB " + puan + "/100 -- panoda " + sira + ". sira." };

const satir = { filename: "/internal-storage-files/konsey/pano.jsonl", payload: JSON.stringify(kayit) };

const gun = new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Istanbul" });   // YYYY-MM-DD
const oturum = {
  filename: "/internal-storage-files/konsey/oturumlar/" + gun + ".jsonl",
  payload: JSON.stringify({
    zaman: kayit.zaman,
    proje: k.proje,
    ilham: k.ilham,
    oneriler: k.konusmalar.map(x => ({ karakter: x.karakter, kodAdi: x.kodAdi, gerekce: x.gerekce, baskanNotu: deg[x.karakter] || "" })),
    kazanan: { kodAdi: kazanan.kodAdi, karakter: kazanan.karakter, puan: puan },
    karar: karar,
    panodakiSira: sira
  })
};
node.status({ fill: "green", shape: "dot", text: kazanan.kodAdi + " " + puan + "/100 -> #" + sira });
return [satir, msg, oturum];

// Bir konsey ajani hata verirse (ajan dugumunun 2. cikisi -> 3 sn bekle -> burasi).
//
// Ajan hatalari cogu zaman gecici: gercek kosuda "Mastra API error 500:
// Agent execution failed - Bad Gateway" geldi (Ders 8.7). Ayni prompt'u ayni
// ajana en fazla 2 kez daha gonderiyoruz; olmazsa konsey dagilir.
//
// Cikislar (03 ile ayni): 1 muhendis | 2 pazarlamaci | 3 sair | 4 baskan | 5 hata

const ENFAZLA = 3;   // toplam deneme (ilk + 2 yeniden)
const k = msg.konsey || {};
const metin = (msg.error && (msg.error.message || msg.error.code)) || "bilinmeyen ajan hatasi";

k.deneme = (k.deneme || 1) + 1;
if (k.sonPrompt && k.sonHedef !== undefined && k.deneme <= ENFAZLA) {
  node.warn("Konsey ajani hata verdi, yeniden deneniyor (" + k.deneme + "/" + ENFAZLA + "): " + metin);
  delete msg.error;
  msg.payload = k.sonPrompt;
  node.status({ fill: "yellow", shape: "ring", text: "yeniden " + k.deneme + "/" + ENFAZLA });
  const cikis = [null, null, null, null, null];
  cikis[k.sonHedef] = msg;
  return cikis;
}

msg.hata = metin + " (" + ENFAZLA + " deneme)";
node.status({ fill: "red", shape: "dot", text: "vazgecildi" });
return [null, null, null, null, msg];

// Konsey dagilirsa (ajan hatasi, bos cevap, dosya hatasi) Submit donup
// kalmasin: kullaniciya ne oldugunu soyle.

const m = msg.hata ||
  (msg.error && (msg.error.message || msg.error.code)) ||
  (msg.payload && msg.payload.error) || "bilinmeyen sebep";
const metin = "Konsey dagildi: " + String(m).slice(0, 250) + " -- Birazdan tekrar dene.";
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
msg.messages = { mesaj: metin };
msg.submission = { proje: (msg.konsey && msg.konsey.proje) || msg.proje || "", sahne: '<div class="konsey-hata">\u{1F4A5} ' + esc(metin) + '</div>' };
delete msg.error;
return msg;

// "Isim Panosu" sayfasi acilirken: pano.jsonl'i okur, puana gore siralar
// (esitlikte once gelen ustte), datagrid'e basar.

const kayitlar = [];
for (const satir of String(msg.payload || "").split(/\r?\n/)) {
  if (!satir.trim()) continue;
  try { const k = JSON.parse(satir); if (k && k.kodAdi) kayitlar.push(k); } catch (e) {}
}
kayitlar.sort((x, y) => (y.puan - x.puan) || String(x.zaman).localeCompare(String(y.zaman)));

const AD = { muhendis: "Alayci Muhendis", pazarlamaci: "Abartili Pazarlamaci", sair: "Dramatik Sair" };
const MADALYA = ["\u{1F947}", "\u{1F948}", "\u{1F949}"];

function yerel(iso) {
  try { return new Date(iso).toLocaleString("tr-TR", { timeZone: "Europe/Istanbul", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }); }
  catch (e) { return iso; }
}

let tablo = kayitlar.map((k, i) => ({
  sira: (MADALYA[i] ? MADALYA[i] + " " : "") + (i + 1),
  kodAdi: k.kodAdi,
  puan: String(k.puan),
  karakter: AD[k.karakter] || k.karakter,
  proje: k.proje,
  zaman: yerel(k.zaman)
}));
if (!tablo.length) tablo = [{ sira: "", kodAdi: "Pano bos -- ilk ismi Konsey sayfasindan sen al!", puan: "", karakter: "", proje: "", zaman: "" }];

msg.submission = { tablo: tablo };
node.status({ fill: "blue", shape: "dot", text: kayitlar.length + " isim" });
return msg;
